package service

import (
	"errors"
	"fmt"
)

var ErrDigestsMismatch = errors.New("found existing attestation with same PURL but different digest")

// ClientFacingError includes a methods to return client friendly detailed error
// messages without including all of the raw error messages generated by the code.
// Returning client friendly details about the error's cause allows clients
// to more easily resolve the issue in their request that caused the error.
type ClientFacingError interface {
	Error() string
	ClientFacingError() string
}

const InternalErrorMsg = "internal error"

// InternalError represents a server error that is not caused by an invalid
// client request. This can be used to represent issues like the inability for
// the server to connect to a datastore.
type InternalError struct {
	wrappedErr error
	message    string
}

func (e *InternalError) Unwrap() error {
	return e.wrappedErr
}

func (e *InternalError) ClientFacingError() string {
	return e.message
}

func (e *InternalError) Error() string {
	return fmt.Sprintf("InternalError: %s", e.wrappedErr.Error())
}

// NewInternalError creates a new InternalError with the default error message.
func NewInternalError(err error) *InternalError {
	return &InternalError{
		wrappedErr: err,
		message:    InternalErrorMsg,
	}
}

// BadRequestError represents an error caused by an invalid client request.
// This can be used to represent requests that include invalid POST body
// content and path arguments.
type BadRequestError struct {
	wrappedErr error
	message    string
}

func (e *BadRequestError) Unwrap() error {
	return e.wrappedErr
}

func (e *BadRequestError) ClientFacingError() string {
	return e.message
}

func (e *BadRequestError) Error() string {
	return fmt.Sprintf("BadRequestError: %s", e.wrappedErr.Error())
}

// NewBadRequestError creates a new BadRequestError with the default error message.
func NewBadRequestError(err error) *BadRequestError {
	return &BadRequestError{
		wrappedErr: err,
		message:    err.Error(),
	}
}

